"use strict";
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const cp = require("node:child_process");
const [root, expected, relative] = process.argv.slice(2);
if (!path.isAbsolute(root) || !/^[a-f0-9]{40}$/.test(expected) ||
    !/^\.local\/checks\/rust-[0-9.]+-[a-z-]+\.json$/.test(relative)) process.exit(2);
const commit = () => cp.execFileSync("git", ["-c", `safe.directory=${root}`, "-C", root,
    "rev-parse", "HEAD"], {encoding: "utf8", timeout: 5000}).trim();
if (commit() !== expected) process.exit(3);
const started = Date.now();
const filename = path.join(root, relative);
const timer = setInterval(() => {
  if (Date.now() - started > 60 * 60 * 1000) process.exit(4);
  try {
    const info = fs.lstatSync(filename);
    if (!info.isFile() || info.size > 16 * 1024 * 1024) process.exit(5);
    const data = fs.readFileSync(filename);
    const report = JSON.parse(data);
    if (typeof report.passed !== "boolean" || !Array.isArray(report.checks)) return;
    const result = {schemaVersion: 1, capturedAt: new Date().toISOString(),
      method: "Read-only watcher in the explicitly selected Forgejo Rust matrix container.",
      sourceCommit: commit(), expectedSourceCommit: expected,
      path: relative, sha256: crypto.createHash("sha256").update(data).digest("hex"), report};
    clearInterval(timer);
    process.stdout.write(JSON.stringify(result) + "\n");
  } catch (_) {
    // Wait for the final report to exist and its ordinary write to finish.
  }
}, 50);
